def next_smallest_palindrome(num: int) -> int:
    def is_all_nines(s: str) -> bool:
        return all(ch == '9' for ch in s)

    s = str(num + 1)  # start checking from the next number
    n = len(s)

    # If all digits are '9', the next palindrome is 10...01 (e.g. 999 -> 1001)
    if is_all_nines(s):
        return int('1' + ('0' * (n - 1)) + '1')

    # Helper to create palindrome by mirroring left to right
    def make_palindrome(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[-2::-1]
        else:
            return left + left[::-1]

    half_len = (n + 1) // 2
    left = s[:half_len]

    palindrome = make_palindrome(left, n % 2 != 0)

    if int(palindrome) >= int(s):
        return int(palindrome)
    else:
        # Increment the left half and remake palindrome
        incremented = str(int(left) + 1)
        if len(incremented) > len(left):  # handle overflow like 999 + 1 -> 1000
            # This means length of palindrome increases by 1
            return int('1' + ('0' * (n - 1)) + '1')
        return int(make_palindrome(incremented, n % 2 != 0))
```

