import math

def min_Jumps(d: int, length: int) -> int:
    if d == 0:
        return 0
    if d == length:
        return 1
    if d < length:
        return 2
    # For d > length, calculate minimum jumps:
    # The minimal number of jumps is the smallest n such that n*length >= d
    # But if d > length and not a multiple, we need to check if one jump can reach exactly (d,0)
    # or if we need more jumps.
    # Actually, if d > length, minimum jumps is ceil(d/length)
    return math.ceil(d / length)
